class TrieNode {
public:
    TrieNode* children[26];
    bool isEnd;
    TrieNode() { 
        isEnd = false;
        for(int i=0; i<26; i++) children[i] = NULL;
    }
};
class Trie {
    TrieNode* root;
public:
    Trie() { root = new TrieNode(); }
    void insert(string word) {
        TrieNode* node = root;
        for(char c : word) {
            if(!node->children[c - 'a']) node->children[c - 'a'] = new TrieNode();
            node = node->children[c - 'a'];
        }
        node->isEnd = true;
    }
};

class WordDictionary {
    TrieNode* root;
public:
    WordDictionary() { root = new TrieNode(); }
    void addWord(string word) { /* standard insert */ }
    bool search(string word) { return searchHelper(word, root, 0); }
    bool searchHelper(string& word, TrieNode* node, int i) {
        if (i == word.size()) return node->isEnd;
        if (word[i] == '.') {
            for (int c = 0; c < 26; c++) {
                if (node->children[c] && searchHelper(word, node->children[c], i + 1)) return true;
            }
            return false;
        } else {
            if (!node->children[word[i] - 'a']) return false;
            return searchHelper(word, node->children[word[i] - 'a'], i + 1);
        }
    }
};
